          {brandEntries.map(([brandId, items]) => {
            const brandName = getBrandName(brandId);
            return (
              <div key={brandId}>
                <div className="flex items-center justify-between mb-5 pb-4 border-b border-gray-100">
                  <div className="flex items-center gap-2.5">
