  "우체국", "수협은행", "대구은행", "부산은행", "경남은행", "광주은행",
  "전북은행", "제주은행",
];

export default function Profile() {
  const { count } = useWishlist();
  const queryClient = useQueryClient();
  const { toast } = useToast();
  const [showDepositForm, setShowDepositForm] = useState(false);
  const [depositAmount, setDepositAmount] = useState("");
  const [bankName, setBankName] = useState("");
  const [depositorName, setDepositorName] = useState("");
  const [isEditing, setIsEditing] = useState(false);
  const [editForm, setEditForm] = useState({
    name: "",
    email: "",
    phone: "",
    address: "",
    bank: "",
    accountNumber: "",
  });

  const memberToken = localStorage.getItem("memberToken");
  const isLoggedIn = memberToken !== null;

  const { data: memberInfo, refetch: refetchMember } = useQuery<MemberInfo>({
    queryKey: ["member-info"],
    queryFn: async () => {
      const res = await fetch("/api/members/me", {
        headers: {
          Authorization: `Bearer ${memberToken}`,
        },
      });
      const data = await res.json();
      if (!data.success) throw new Error(data.error);
      return data.data;
    },
    enabled: isLoggedIn,
  });

  const { data: depositRequests } = useQuery<DepositRequest[]>({
    queryKey: ["deposit-requests"],
    queryFn: async () => {
      const res = await fetch("/api/members/deposit-requests", {
        headers: {
          Authorization: `Bearer ${memberToken}`,
        },
      });
      const data = await res.json();
      if (!data.success) throw new Error(data.error);
      return data.data;
    },
    enabled: isLoggedIn,
  });

  const { data: pointTransactions } = useQuery<PointTransaction[]>({
    queryKey: ["point-transactions"],
    queryFn: async () => {
      const res = await fetch("/api/members/point-transactions", {
        headers: {
          Authorization: `Bearer ${memberToken}`,
        },
      });
      const data = await res.json();
      if (!data.success) throw new Error(data.error);
      return data.data;
    },
    enabled: isLoggedIn,
  });

  const memberId = localStorage.getItem("memberId");

  const { data: memberOrders } = useQuery<Order[]>({
    queryKey: ["member-orders", memberId],
    queryFn: async () => {
      const params = new URLSearchParams();
      if (memberId) params.append("memberId", memberId);

      const res = await fetch(`/api/members/orders?${params.toString()}`, {
        headers: {
          Authorization: `Bearer ${memberToken}`,
        },
      });
      const data = await res.json();
      if (!data.success) throw new Error(data.error);
      return data.data;
    },
    enabled: isLoggedIn && !!memberId,
  });

  const depositMutation = useMutation({
    mutationFn: async (request: { amount: number; bankName: string; depositorName: string }) => {
      const res = await fetch("/api/members/deposit-requests", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${memberToken}`,
        },
        body: JSON.stringify(request),
      });
      const data = await res.json();
      if (!data.success) throw new Error(data.error);
      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["deposit-requests"] });
      setShowDepositForm(false);
      setDepositAmount("");
      setBankName("");
      setDepositorName("");
      alert("입금신청이 접수되었습니다. 관리자 승인 후 포인트가 충전됩니다.");
    },
    onError: (error: Error) => {
      alert(error.message);
    },
  });

  const profileUpdateMutation = useMutation({
    mutationFn: async (data: { name: string; email: string; phone: string; address: string; bank: string; accountNumber: string }) => {
      const res = await fetch("/api/members/me", {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${memberToken}`,
        },
        body: JSON.stringify(data),
      });
      const result = await res.json();
      if (!result.success) throw new Error(result.error);
      return result;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["member-info"] });
      setIsEditing(false);
      toast({
        title: "수정 완료",
        description: "개인정보가 성공적으로 수정되었습니다.",
      });
    },
    onError: (error: Error) => {
      toast({
        title: "수정 실패",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  const handleStartEditing = () => {
    if (memberInfo) {
      setEditForm({
        name: memberInfo.name || "",
        email: memberInfo.email || "",
        phone: memberInfo.phone || "",
        address: memberInfo.address || "",
        bank: memberInfo.bank || "",
        accountNumber: memberInfo.accountNumber || "",
      });
      setIsEditing(true);
    }
  };

  const handleSaveProfile = () => {
    profileUpdateMutation.mutate(editForm);
  };

  const handleCancelEdit = () => {
    setIsEditing(false);
  };

  const handleLogout = () => {
    localStorage.removeItem("memberToken");
    localStorage.removeItem("memberName");
    localStorage.removeItem("memberEmail");
    localStorage.removeItem("memberId");
    window.location.reload();
  };

  const handleDepositSubmit = () => {
    if (memberInfo?.isFrozen) {
      alert("계정이 동결되어 입금신청을 할 수 없습니다.");
      return;
    }

    if (!depositAmount || !bankName || !depositorName) {
      alert("모든 필드를 입력해주세요.");
      return;
    }

    const amount = parseInt(depositAmount.replace(/,/g, ""));
    if (isNaN(amount) || amount <= 0) {
      alert("유효한 금액을 입력해주세요.");
      return;
    }

    depositMutation.mutate({ amount, bankName, depositorName });
  };

  const formatDate = (dateStr: string) => {
    return new Date(dateStr).toLocaleDateString("ko-KR", {
      year: "numeric",
      month: "long",
      day: "numeric",
      hour: "2-digit",
      minute: "2-digit",
    });
  };

  const formatSimpleDate = (dateStr: string) => {
    return new Date(dateStr).toLocaleDateString("ko-KR", {
      year: "numeric",
      month: "long",
      day: "numeric",
    });
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case "pending":
        return (
          <span className="inline-flex items-center gap-1 px-2 py-1 rounded-full text-xs font-medium bg-yellow-100 text-yellow-700">
            <Clock className="w-3 h-3" />
            대기중
          </span>
        );
      case "approved":
        return (
          <span className="inline-flex items-center gap-1 px-2 py-1 rounded-full text-xs font-medium bg-green-100 text-green-700">
            <CheckCircle className="w-3 h-3" />
            승인됨
          </span>
        );
      case "rejected":
        return (
          <span className="inline-flex items-center gap-1 px-2 py-1 rounded-full text-xs font-medium bg-red-100 text-red-700">
            <XCircle className="w-3 h-3" />
            거부됨
          </span>
        );
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 font-sans">
      <Header />

      <main className="container-custom py-6 md:py-12 px-4">
        <div className="max-w-2xl mx-auto">
          {memberInfo?.isFrozen && (
            <div className="mb-4 md:mb-6 p-3 md:p-4 bg-red-50 border border-red-200 rounded-xl flex items-start gap-3">
              <AlertTriangle className="w-5 h-5 text-red-500 mt-0.5 flex-shrink-0" />
              <div>
                <h3 className="font-bold text-red-700 text-sm md:text-base">계정이 동결되었습니다</h3>
                <p className="text-xs md:text-sm text-red-600 mt-1">
                  현재 계정이 동결 상태입니다. 일부 서비스 이용이 제한됩니다.
                  문의사항은 고객센터로 연락해주세요.
                </p>
              </div>
            </div>
          )}

          <div className="bg-white rounded-xl shadow-sm overflow-hidden">
            <div className="bg-gradient-to-r from-amber-500 to-yellow-500 p-4 md:p-8 text-white">
              <div className="flex items-center gap-3 md:gap-4">
                <div className="w-14 h-14 md:w-20 md:h-20 bg-white/20 rounded-full flex items-center justify-center flex-shrink-0">
                  <User className="w-7 h-7 md:w-10 md:h-10" />
                </div>
                <div className="min-w-0 flex-1">
                  {isLoggedIn ? (
                    <>
                      <h1 className="text-lg md:text-2xl font-bold truncate" data-testid="text-profile-name">
                        {memberInfo?.name || localStorage.getItem("memberName") || "회원"}님
                      </h1>
                      <p className="text-white/80 text-xs md:text-sm mt-1 truncate">{memberInfo?.email || localStorage.getItem("memberEmail")}</p>
                    </>
                  ) : (
                    <>
                      <h1 className="text-lg md:text-2xl font-bold">로그인이 필요합니다</h1>
                      <p className="text-white/80 text-xs md:text-sm mt-1">로그인하시면 더 많은 혜택을 받으실 수 있습니다</p>
                    </>
                  )}
                </div>
              </div>
            </div>

            {!isLoggedIn ? (
              <div className="p-8 text-center">
                <p className="text-gray-500 mb-6">
                  로그인하여 주문 내역, 찜 목록 등 다양한 서비스를 이용해보세요.
                </p>
                <div className="flex gap-4 justify-center">
                  <Link href="/login">
                    <Button className="bg-primary hover:bg-primary/90">
                      로그인
                    </Button>
                  </Link>
                  <Link href="/signup">
                    <Button variant="outline">
                      회원가입
                    </Button>
                  </Link>
                </div>
              </div>
            ) : (
              <div className="p-4 md:p-6">
                <div className="grid grid-cols-3 gap-2 md:gap-4 mb-4 md:mb-6">
                  <Link href="/cart">
                    <div className="text-center p-2 md:p-4 bg-gray-50 rounded-lg hover:bg-gray-100 transition-colors cursor-pointer">
                      <Heart className="w-6 h-6 md:w-8 md:h-8 text-primary mx-auto mb-1 md:mb-2" />
                      <div className="text-lg md:text-2xl font-bold text-gray-900">{count}</div>
                      <div className="text-[10px] md:text-xs text-gray-500">찜 목록</div>
                    </div>
                  </Link>
                  <div className="text-center p-2 md:p-4 bg-gray-50 rounded-lg">
                    <Package className="w-6 h-6 md:w-8 md:h-8 text-primary mx-auto mb-1 md:mb-2" />
                    <div className="text-lg md:text-2xl font-bold text-gray-900" data-testid="text-order-count">{memberOrders?.length || 0}</div>
                    <div className="text-[10px] md:text-xs text-gray-500">주문 내역</div>
                  </div>
                  <div className="text-center p-2 md:p-4 bg-gradient-to-br from-amber-50 to-yellow-50 rounded-lg border border-amber-200">
                    <Wallet className="w-6 h-6 md:w-8 md:h-8 text-amber-600 mx-auto mb-1 md:mb-2" />
                    <div className="text-lg md:text-2xl font-bold text-amber-700" data-testid="text-point-balance">
                      {(memberInfo?.pointBalance || 0).toLocaleString()}
                    </div>
                    <div className="text-[10px] md:text-xs text-amber-600 font-medium">포인트</div>
                  </div>
                </div>

                <Tabs defaultValue="info" className="w-full">
                  <TabsList className="w-full grid grid-cols-5 h-auto">
                    <TabsTrigger value="info" className="text-xs md:text-sm py-2 px-1 md:px-3">내 정보</TabsTrigger>
                    <TabsTrigger value="orders" className="text-xs md:text-sm py-2 px-1 md:px-3">주문내역</TabsTrigger>
                    <TabsTrigger value="menu" className="text-xs md:text-sm py-2 px-1 md:px-3">메뉴</TabsTrigger>
                    <TabsTrigger value="deposit" className="text-xs md:text-sm py-2 px-1 md:px-3">입금신청</TabsTrigger>
                    <TabsTrigger value="points" className="text-xs md:text-sm py-2 px-1 md:px-3">포인트</TabsTrigger>
                  </TabsList>

                  <TabsContent value="info" className="mt-4">
                    <div className="space-y-4">
                      {!isEditing && (
                        <div className="flex justify-end">
                          <Button
                            variant="outline"
                            size="sm"
                            onClick={handleStartEditing}
                            className="gap-2"
                          >
                            <Pencil className="w-4 h-4" />
                            정보 수정
                          </Button>
                        </div>
                      )}

                      {isEditing ? (
                        <div className="bg-gray-50 rounded-lg p-4 space-y-4">
                          <div className="flex justify-between items-center mb-4">
                            <h3 className="font-bold text-gray-900">정보 수정</h3>
                            <div className="flex gap-2">
                              <Button
                                variant="outline"
                                size="sm"
                                onClick={handleCancelEdit}
                                className="gap-1"
                              >
                                <X className="w-4 h-4" />
                                취소
                              </Button>
                              <Button
                                size="sm"
                                onClick={handleSaveProfile}
                                disabled={profileUpdateMutation.isPending}
                                className="gap-1 bg-primary"
                              >
                                <Save className="w-4 h-4" />
                                저장
                              </Button>
                            </div>
                          </div>

                          <div className="space-y-4">
                            <div>
                              <Label className="text-xs text-gray-500">이름</Label>
                              <Input
                                value={editForm.name}
                                onChange={(e) => setEditForm({ ...editForm, name: e.target.value })}
                                placeholder="이름"
                              />
                            </div>
                            <div>
                              <Label className="text-xs text-gray-500">이메일</Label>
                              <Input
                                type="email"
                                value={editForm.email}
                                onChange={(e) => setEditForm({ ...editForm, email: e.target.value })}
                                placeholder="이메일"
                              />
                            </div>
                            <div>
                              <Label className="text-xs text-gray-500">휴대폰</Label>
                              <Input
                                value={editForm.phone}
                                onChange={(e) => setEditForm({ ...editForm, phone: e.target.value })}
                                placeholder="휴대폰 번호"
                              />
                            </div>
                            <div>
                              <Label className="text-xs text-gray-500">주소</Label>
                              <Input
                                value={editForm.address}
                                onChange={(e) => setEditForm({ ...editForm, address: e.target.value })}
                                placeholder="주소"
                              />
                            </div>
                            <h4 className="font-bold text-gray-900 mt-4">환급 계좌 정보</h4>
                            <div>
                              <Label className="text-xs text-gray-500">은행</Label>
                              <select
                                className="w-full h-10 px-3 border border-gray-200 rounded-md bg-white"
                                value={editForm.bank}
                                onChange={(e) => setEditForm({ ...editForm, bank: e.target.value })}
                              >
                                <option value="">은행 선택</option>
                                {BANKS.map((bank) => (
                                  <option key={bank} value={bank}>{bank}</option>
                                ))}
                              </select>
                            </div>
                            <div>
                              <Label className="text-xs text-gray-500">계좌번호</Label>
                              <Input
                                value={editForm.accountNumber}
                                onChange={(e) => setEditForm({ ...editForm, accountNumber: e.target.value })}
                                placeholder="계좌번호"
                              />
                            </div>
                          </div>
                        </div>
                      ) : (
                        <div className="bg-gray-50 rounded-lg p-4 space-y-4">
                          <h3 className="font-bold text-gray-900 mb-4">기본 정보</h3>

                          <div className="flex items-center gap-3 py-2 border-b border-gray-200">
                            <User className="w-5 h-5 text-gray-400" />
                            <div className="flex-1">
                              <p className="text-xs text-gray-500">이름</p>
                              <p className="text-gray-900 font-medium">{memberInfo?.name || "-"}</p>
                            </div>
                          </div>

                          <div className="flex items-center gap-3 py-2 border-b border-gray-200">
                            <Mail className="w-5 h-5 text-gray-400" />
                            <div className="flex-1">
                              <p className="text-xs text-gray-500">이메일</p>
                              <p className="text-gray-900 font-medium">{memberInfo?.email || "-"}</p>
                            </div>
                          </div>

                          <div className="flex items-center gap-3 py-2 border-b border-gray-200">
                            <Phone className="w-5 h-5 text-gray-400" />
                            <div className="flex-1">
                              <p className="text-xs text-gray-500">휴대폰</p>
                              <p className="text-gray-900 font-medium">{memberInfo?.phone || "-"}</p>
                            </div>
                          </div>

                          <div className="flex items-center gap-3 py-2 border-b border-gray-200">
                            <MapPin className="w-5 h-5 text-gray-400" />
                            <div className="flex-1">
                              <p className="text-xs text-gray-500">주소</p>
                              <p className="text-gray-900 font-medium">{memberInfo?.address || "-"}</p>
                            </div>
                          </div>

                          <h3 className="font-bold text-gray-900 mt-6 mb-4">환급 계좌 정보</h3>

                          <div className="flex items-center gap-3 py-2 border-b border-gray-200">
                            <Building2 className="w-5 h-5 text-gray-400" />
                            <div className="flex-1">
                              <p className="text-xs text-gray-500">은행</p>
                              <p className="text-gray-900 font-medium">{memberInfo?.bank || "-"}</p>
                            </div>
                          </div>

                          <div className="flex items-center gap-3 py-2 border-b border-gray-200">
                            <CreditCard className="w-5 h-5 text-gray-400" />
                            <div className="flex-1">
                              <p className="text-xs text-gray-500">계좌번호</p>
                              <p className="text-gray-900 font-medium">{memberInfo?.accountNumber || "-"}</p>
                            </div>
                          </div>

                          <div className="flex items-center gap-3 py-2">
                            <Clock className="w-5 h-5 text-gray-400" />
                            <div className="flex-1">
                              <p className="text-xs text-gray-500">가입일</p>
                              <p className="text-gray-900 font-medium">
                                {memberInfo?.createdAt ? formatSimpleDate(memberInfo.createdAt) : "-"}
                              </p>
                            </div>
                          </div>
                        </div>
                      )}
                    </div>
                  </TabsContent>

                  <TabsContent value="orders" className="mt-4">
                    <div className="space-y-4">
                      <h3 className="font-bold text-gray-900">주문 내역</h3>
                      {memberOrders && memberOrders.length > 0 ? (
                        <div className="space-y-3">
                          {memberOrders.map((order) => (
                            <div key={order.id} className="bg-white border border-gray-200 rounded-lg p-4" data-testid={`order-item-${order.id}`}>
                              <div className="flex justify-between items-center mb-3 pb-2 border-b border-gray-100">
                                <span className="text-xs font-mono bg-gray-100 px-2 py-1 rounded text-gray-600">주문번호: {order.orderNumber}</span>
                                <span className="text-xs text-gray-400">{new Date(order.createdAt).toLocaleDateString("ko-KR")}</span>
                              </div>
                              <div className="flex justify-between items-start mb-2">
                                <div>
                                  <h4 className="font-medium text-gray-900">{order.productName}</h4>
                                  <p className="text-sm text-gray-500">수량: {order.quantity}개</p>
                                </div>
                                <div className="text-right">
                                  <p className="font-bold text-primary">{Number(order.totalAmount || 0).toLocaleString()}원</p>
                                </div>
                              </div>
                              <div className="flex gap-2 mt-3">
                                <span className={`text-xs px-2 py-1 rounded-full ${
                                  order.status === "delivered" ? "bg-green-100 text-green-700" :
                                  order.status === "shipped" ? "bg-blue-100 text-blue-700" :
                                  order.status === "confirmed" ? "bg-yellow-100 text-yellow-700" :
                                  order.status === "cancelled" ? "bg-red-100 text-red-700" :
                                  "bg-gray-100 text-gray-700"
                                }`}>
                                  {order.status === "pending" && "대기중"}
                                  {order.status === "confirmed" && "확인됨"}
                                  {order.status === "shipped" && "배송중"}
                                  {order.status === "delivered" && "배송완료"}
                                  {order.status === "cancelled" && "취소됨"}
                                </span>
                                <span className={`text-xs px-2 py-1 rounded-full ${
                                  order.paymentStatus === "paid" ? "bg-green-100 text-green-700" :
                                  order.paymentStatus === "refunded" ? "bg-red-100 text-red-700" :
                                  "bg-amber-100 text-amber-700"
                                }`}>
                                  {order.paymentStatus === "pending" && "결제 대기"}
                                  {order.paymentStatus === "paid" && "결제 완료"}
                                  {order.paymentStatus === "refunded" && "환불됨"}
                                </span>
                              </div>
                            </div>
                          ))}
                        </div>
                      ) : (
                        <div className="text-center py-8 text-gray-500">
                          <Package className="w-12 h-12 mx-auto mb-3 text-gray-300" />
                          <p>주문 내역이 없습니다.</p>
                        </div>
                      )}
                    </div>
                  </TabsContent>

                  <TabsContent value="menu" className="mt-4">
                    <div className="space-y-2">
                      <Link href="/cart">
                        <div className="flex items-center justify-between p-4 hover:bg-gray-50 rounded-lg cursor-pointer transition-colors" data-testid="link-wishlist">
                          <div className="flex items-center gap-3">
                            <Heart className="w-5 h-5 text-gray-400" />
                            <span className="text-gray-700">찜 목록</span>
                          </div>
                          <ChevronRight className="w-5 h-5 text-gray-400" />
                        </div>
                      </Link>

                      <div className="flex items-center justify-between p-4 hover:bg-gray-50 rounded-lg cursor-pointer transition-colors">
                        <div className="flex items-center gap-3">
                          <Package className="w-5 h-5 text-gray-400" />
                          <span className="text-gray-700">주문/배송 조회</span>
                        </div>
                        <ChevronRight className="w-5 h-5 text-gray-400" />
                      </div>

                      <button
                        onClick={handleLogout}
                        className="w-full flex items-center justify-between p-4 hover:bg-red-50 rounded-lg cursor-pointer transition-colors text-left"
                        data-testid="button-logout"
                      >
                        <div className="flex items-center gap-3">
                          <LogOut className="w-5 h-5 text-red-400" />
                          <span className="text-red-500">로그아웃</span>
                        </div>
                      </button>
                    </div>
                  </TabsContent>

                  <TabsContent value="deposit" className="mt-4">
                    <div className="space-y-4">
                      <div className="p-4 bg-amber-50 border border-amber-200 rounded-lg">
                        <h3 className="font-bold text-amber-800 mb-2">입금 안내</h3>
                        <div className="text-sm text-amber-700">
                          <p>입금 관련 상세 안내는 카카오톡 고객센터로 연락 바랍니다.</p>
                        </div>
                      </div>

                      <Dialog open={showDepositForm} onOpenChange={setShowDepositForm}>
                        <DialogTrigger asChild>
                          <Button 
                            className="w-full bg-primary hover:bg-primary/90"
                            disabled={memberInfo?.isFrozen}
                          >
                            <Plus className="w-4 h-4 mr-2" />
                            입금 신청하기
                          </Button>
                        </DialogTrigger>
                        <DialogContent>
                          <DialogHeader>
                            <DialogTitle>입금 신청</DialogTitle>
                          </DialogHeader>
                          <div className="space-y-4 pt-4">
                            <div>
                              <Label htmlFor="amount">입금 금액 (원)</Label>
                              <Input
                                id="amount"
                                type="text"
                                placeholder="예: 100,000"
                                value={depositAmount}
                                onChange={(e) => setDepositAmount(e.target.value)}
                              />
                            </div>
                            <div>
                              <Label htmlFor="bankName">입금 은행</Label>
                              <Input
                                id="bankName"
                                placeholder="예: 국민은행"
                                value={bankName}
                                onChange={(e) => setBankName(e.target.value)}
                              />
                            </div>
                            <div>
                              <Label htmlFor="depositorName">입금자명</Label>
                              <Input
                                id="depositorName"
                                placeholder="입금시 표시되는 이름"
                                value={depositorName}
                                onChange={(e) => setDepositorName(e.target.value)}
                              />
                            </div>
                            <Button
                              className="w-full"
                              onClick={handleDepositSubmit}
                              disabled={depositMutation.isPending}
                            >
                              {depositMutation.isPending ? "처리중..." : "신청하기"}
                            </Button>
                          </div>
                        </DialogContent>
                      </Dialog>

                      <div className="space-y-3">
                        <h3 className="font-bold text-gray-900">입금 신청 내역</h3>
                        {!depositRequests?.length ? (
                          <p className="text-sm text-gray-500 text-center py-8">
                            입금 신청 내역이 없습니다.
                          </p>
                        ) : (
                          depositRequests.map((request) => (
                            <div
                              key={request.id}
                              className="p-4 border rounded-lg bg-white"
                            >
                              <div className="flex justify-between items-start mb-2">
                                <div className="font-bold text-lg">
                                  {request.amount.toLocaleString()}원
                                </div>
                                {getStatusBadge(request.status)}
                              </div>
                              <div className="text-sm text-gray-500 space-y-1">
                                <p>입금자: {request.depositorName} ({request.bankName})</p>
                                <p>신청일: {formatDate(request.requestedAt)}</p>
                                {request.processedAt && (
                                  <p>처리일: {formatDate(request.processedAt)}</p>
                                )}
                                {request.adminNote && (
                                  <p className="text-amber-600">메모: {request.adminNote}</p>
                                )}
                              </div>
                            </div>
                          ))
                        )}
                      </div>
                    </div>
                  </TabsContent>

                  <TabsContent value="points" className="mt-4">
                    <div className="space-y-3">
                      <div className="flex justify-between items-center">
                        <h3 className="font-bold text-gray-900">포인트 사용 내역</h3>
                        <span className="text-sm text-gray-500">
                          현재 잔액: <span className="font-bold text-primary">{(memberInfo?.pointBalance || 0).toLocaleString()}P</span>
                        </span>
                      </div>

                      {!pointTransactions?.length ? (
                        <p className="text-sm text-gray-500 text-center py-8">
                          포인트 내역이 없습니다.
                        </p>
                      ) : (
                        pointTransactions.map((transaction) => (
                          <div
                            key={transaction.id}
                            className="p-4 border rounded-lg bg-white flex justify-between items-center"
                          >
                            <div>
                              <p className="font-medium text-gray-900">{transaction.description}</p>
                              <p className="text-xs text-gray-500">{formatDate(transaction.createdAt)}</p>
                            </div>
                            <div className="text-right">
                              <p className={`font-bold ${transaction.amount >= 0 ? "text-green-600" : "text-red-600"}`}>
                                {transaction.amount >= 0 ? "+" : ""}{transaction.amount.toLocaleString()}P
                              </p>
                              <p className="text-xs text-gray-500">
                                잔액: {transaction.balanceAfter.toLocaleString()}P
                              </p>
                            </div>
                          </div>
                        ))
                      )}
                    </div>
                  </TabsContent>
                </Tabs>
              </div>
            )}
          </div>

          <div className="mt-6 p-6 bg-white rounded-xl shadow-sm">
            <h2 className="font-bold text-gray-900 mb-4">고객 지원</h2>
            <div className="space-y-3 text-sm text-gray-600">
              <div className="flex justify-between">
                <span>운영시간</span>
                <span>평일 09:00 - 18:00</span>
              </div>
              <div className="flex justify-between">
                <span>이메일</span>
                <span>support@cheongdam-edition.com</span>
              </div>
            </div>
            <Link href="/support">
              <Button variant="outline" className="w-full mt-4">
                고객센터 바로가기
              </Button>
            </Link>
          </div>
        </div>
      </main>

      <Footer />
    </div>
  );
}

client/src/pages/Cart.tsx.content:
import { Header } from "@/components/layout/Header";
import { Footer } from "@/components/layout/Footer";
import { Button } from "@/components/ui/button";
import { Trash2, ShoppingBag, Heart, ArrowRight, CreditCard, Building2 } from "lucide-react";
import { Link } from "wouter";
import { useWishlist } from "@/contexts/WishlistContext";
import { useToast } from "@/hooks/use-toast";
import { useState, useEffect } from "react";
import { useLocation } from "wouter";
import { CardPaymentForm } from "@/components/checkout/CardPaymentForm";
import { cn } from "@/lib/utils";
import { getProxiedImageUrl, DEFAULT_IMAGE } from "@/lib/imageProxy";

type PaymentMethod = "card" | "bank" | null;
type CheckoutStep = "cart" | "payment" | "complete";

export default function Cart() {
  const { items, removeItem, clearWishlist } = useWishlist();
  const { toast } = useToast();
  const [, setLocation] = useLocation();
  const [step, setStep] = useState<CheckoutStep>("cart");
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod>(null);
  const [itemOptions, setItemOptions] = useState<Record<string, { size: string; color: string }>>({});

  const updateItemOption = (itemId: string, field: "size" | "color", value: string) => {
    setItemOptions(prev => ({
      ...prev,
      [itemId]: { ...prev[itemId] || { size: "", color: "" }, [field]: value },
    }));
  };

  const [depositAccount, setDepositAccount] = useState<{
    bankName: string;
    accountNumber: string;
    accountHolder: string;
  } | null>(null);

  useEffect(() => {
    const fetchDepositAccount = async () => {
      try {
        const res = await fetch("/api/settings/deposit_account");
        const data = await res.json();
        if (data.success && data.data?.value) {
          try {
            const parsed = JSON.parse(data.data.value);
            if (parsed.bankName && parsed.accountNumber) {
              setDepositAccount(parsed);
            }
          } catch {}
        }
      } catch {}
    };
    fetchDepositAccount();
  }, []);

  const handleRemove = (id: string, name: string) => {
    removeItem(id);
    toast({
      title: "삭제 완료",
      description: `${name}이(가) 찜 목록에서 삭제되었습니다.`,
    });
  };

  const totalPrice = items.reduce((sum, item) => {
    return sum + (item.price || 0);
  }, 0);

  return (
    <div className="min-h-screen bg-white font-sans">
      <Header />

      <main className="container-custom py-12">
        <div className="max-w-4xl mx-auto">
          <div className="flex items-center gap-3 mb-8">
            <Heart className="w-8 h-8 text-primary" />
            <h1 className="text-3xl font-bold text-gray-900" data-testid="text-cart-title">찜 목록</h1>
          </div>

          {items.length === 0 ? (
            <div className="text-center py-20 bg-gray-50 rounded-lg">
              <ShoppingBag className="w-16 h-16 text-gray-300 mx-auto mb-4" />
              <p className="text-gray-500 text-lg mb-2">찜한 상품이 없습니다</p>
              <p className="text-gray-400 text-sm mb-6">하트 아이콘을 눌러 마음에 드는 상품을 담아보세요</p>
              <Link href="/">
                <Button className="bg-primary hover:bg-primary/90">
                  쇼핑 계속하기
                  <ArrowRight className="w-4 h-4 ml-2" />
                </Button>
              </Link>
            </div>
          ) : (
            <>
              <div className="flex justify-between items-center mb-6 pb-4 border-b">
                <p className="text-gray-600">
                  총 <span className="font-bold text-primary">{items.length}</span>개의 상품
                </p>
                <Button 
                  variant="outline" 
                  size="sm" 
                  onClick={() => {
                    clearWishlist();
                    toast({ title: "전체 삭제 완료", description: "찜 목록이 비워졌습니다." });
                  }}
                  data-testid="button-clear-cart"
                >
                  전체 삭제
                </Button>
              </div>

              <div className="space-y-4">
                {items.map((item) => (
                  <div 
                    key={item.id} 
                    className="flex gap-4 p-4 bg-white border rounded-lg hover:shadow-md transition-shadow"
                    data-testid={`cart-item-${item.id}`}
                  >
                    <Link href={`/product/${item.id}`}>
                      <div className="w-24 h-24 bg-gray-50 rounded-lg overflow-hidden flex-shrink-0">
                        <img 
                          src={getProxiedImageUrl(item.imageUrl) || DEFAULT_IMAGE} 
                          alt={item.name}
                          className="w-full h-full object-cover"
                          onError={(e) => {
                            const target = e.target as HTMLImageElement;
                            target.src = DEFAULT_IMAGE;
                          }}
                        />
                      </div>
                    </Link>

                    <div className="flex-1 min-w-0">
                      <div className="flex items-start justify-between">
                        <Link href={`/product/${item.id}`}>
                          <h3 className="font-bold text-gray-900 hover:text-primary transition-colors line-clamp-2">
                            {item.name}
                          </h3>
                        </Link>
                        <Button
                          variant="ghost"
                          size="icon"
                          onClick={() => handleRemove(item.id, item.name)}
                          className="text-gray-400 hover:text-red-500 shrink-0 -mt-1 -mr-2"
                          data-testid={`button-remove-${item.id}`}
                        >
                          <Trash2 className="w-4 h-4" />
                        </Button>
                      </div>
                      <div className="mt-1">
                        <span className="text-lg font-bold text-primary">{item.price.toLocaleString()}</span>
                        <span className="text-sm text-gray-500">원</span>
                      </div>
                      <div className="mt-2 grid grid-cols-2 gap-2">
                        <input
                          type="text"
                          placeholder="사이즈"
                          value={itemOptions[item.id]?.size || ""}
                          onChange={(e) => updateItemOption(item.id, "size", e.target.value)}
                          className="w-full px-2 py-1.5 text-sm border border-gray-300 rounded focus:outline-none focus:border-primary"
                          data-testid={`input-size-${item.id}`}
                        />
                        <input
                          type="text"
                          placeholder="색상"
                          value={itemOptions[item.id]?.color || ""}
                          onChange={(e) => updateItemOption(item.id, "color", e.target.value)}
                          className="w-full px-2 py-1.5 text-sm border border-gray-300 rounded focus:outline-none focus:border-primary"
                          data-testid={`input-color-${item.id}`}
                        />
                      </div>
                    </div>
                  </div>
                ))}
              </div>

              {step === "cart" && (
                <div className="mt-8 p-6 bg-gray-50 rounded-lg">
                  <div className="flex justify-between items-center mb-4">
                    <span className="text-gray-600">총 상품 금액</span>
                    <span className="text-2xl font-bold text-primary">
                      {totalPrice.toLocaleString()}원
                    </span>
                  </div>
                  <Button 
                    className="w-full bg-primary hover:bg-primary/90 h-12 text-lg"
                    onClick={() => setStep("payment")}
                    data-testid="button-checkout"
                  >
                    구매하기
                  </Button>
                </div>
              )}

              {step === "payment" && (
                <div className="mt-8 space-y-6">
                  <div className="flex items-center gap-2 mb-4">
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => {
                        setStep("cart");
                        setPaymentMethod(null);
                      }}
                    >
                      ← 장바구니로 돌아가기
                    </Button>
                  </div>

                  <div className="p-6 bg-gray-50 rounded-lg">
                    <h3 className="text-lg font-bold mb-4">결제 수단 선택</h3>
                    <div className="grid grid-cols-2 gap-4">
                      <button
                        onClick={() => setPaymentMethod("card")}
                        className={cn(
                          "p-4 border-2 rounded-lg flex flex-col items-center gap-2 transition-all",
                          paymentMethod === "card"
                            ? "border-primary bg-primary/5"
                            : "border-gray-200 hover:border-gray-300"
                        )}
                        data-testid="button-payment-card"
                      >
                        <CreditCard className={cn(
                          "w-8 h-8",
                          paymentMethod === "card" ? "text-primary" : "text-gray-400"
                        )} />
                        <span className={cn(
                          "font-medium",
                          paymentMethod === "card" ? "text-primary" : "text-gray-600"
                        )}>
                          카드결제
                        </span>
                      </button>

                      <button
                        onClick={() => setPaymentMethod("bank")}
                        className={cn(
                          "p-4 border-2 rounded-lg flex flex-col items-center gap-2 transition-all",
                          paymentMethod === "bank"
                            ? "border-primary bg-primary/5"
                            : "border-gray-200 hover:border-gray-300"
                        )}
                        data-testid="button-payment-bank"
                      >
                        <Building2 className={cn(
                          "w-8 h-8",
                          paymentMethod === "bank" ? "text-primary" : "text-gray-400"
                        )} />
                        <span className={cn(
                          "font-medium",
                          paymentMethod === "bank" ? "text-primary" : "text-gray-600"
                        )}>
                          무통장입금
                        </span>
                      </button>
                    </div>
                  </div>

                  {paymentMethod === "card" && (
                    <div className="p-6 bg-white border rounded-lg">
                      <CardPaymentForm
                        totalAmount={totalPrice}
                        onSubmit={(isValid) => {
                          if (isValid) {
                            setStep("complete");
                            toast({
                              title: "결제 요청 완료",
                              description: "결제 승인 대기 중입니다.",
                            });
                          }
                        }}
                      />
                    </div>
                  )}

                  {paymentMethod === "bank" && (
                    <div className="p-6 bg-white border rounded-lg">
                      <h3 className="text-lg font-bold mb-4">무통장입금 안내</h3>
                      <div className="space-y-3 text-sm">
                        <div className="p-4 bg-gray-50 rounded-lg">
                          <p className="font-medium">입금 계좌</p>
                          {depositAccount ? (
                            <>
                              <p className="text-lg font-bold mt-1">{depositAccount.bankName} {depositAccount.accountNumber}</p>
                              <p className="text-gray-500">예금주: {depositAccount.accountHolder}</p>
                            </>
                          ) : (
                            <p className="text-gray-400 mt-1">계좌 정보를 불러오는 중...</p>
                          )}
                        </div>
                        <div className="p-4 bg-yellow-50 rounded-lg text-yellow-800">
                          <p>• 입금 확인 후 상품이 발송됩니다</p>
                          <p>• 24시간 이내 미입금 시 주문이 취소됩니다</p>
                        </div>
                      </div>
                      <div className="mt-6 pt-4 border-t">
                        <div className="flex justify-between items-center mb-4">
                          <span className="text-gray-600">결제 금액</span>
                          <span className="text-2xl font-bold text-primary">
                            {totalPrice.toLocaleString()}원
                          </span>
                        </div>
                        <Button
                          className="w-full h-12 text-lg"
                          onClick={() => {
                            const itemsWithOptions = items.map(item => ({
                              ...item,
                              selectedSize: itemOptions[item.id]?.size || "",
                              selectedColor: itemOptions[item.id]?.color || "",
                            }));
                            sessionStorage.setItem("cartOrderItems", JSON.stringify(itemsWithOptions));
                            sessionStorage.setItem("cartPaymentMethod", "bank");
                            setLocation("/order/cart");
                          }}
                          data-testid="button-bank-submit"
                        >
                          주문하기
                        </Button>
                      </div>
                    </div>
                  )}
                </div>
              )}

              {step === "complete" && (
                <div className="mt-8 p-8 bg-green-50 rounded-lg text-center">
                  <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-4">
                    <svg className="w-8 h-8 text-green-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                    </svg>
                  </div>
                  <h3 className="text-xl font-bold text-green-800 mb-2">
                    {paymentMethod === "card" ? "결제 대기중" : "주문이 완료되었습니다"}
                  </h3>
                  <p className="text-green-600 mb-6">
                    {paymentMethod === "card" 
                      ? "결제 승인을 기다리고 있습니다. 마이페이지에서 확인하세요."
                      : "입금 확인 후 상품이 발송됩니다."
                    }
                  </p>
                  <div className="flex gap-4 justify-center">
                    <Link href="/profile">
                      <Button variant="outline">주문 내역 보기</Button>
                    </Link>
                    <Link href="/">
                      <Button>쇼핑 계속하기</Button>
                    </Link>
                  </div>
                </div>
              )}
            </>
          )}
        </div>
      </main>

      <Footer />
    </div>
  );
}

client/src/pages/Notices.tsx.content:
import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { Link } from "wouter";
import { Bell, ChevronRight, Home, ChevronDown, ChevronUp, Pin } from "lucide-react";
import { Header } from "@/components/layout/Header";
import { Footer } from "@/components/layout/Footer";

interface Notice {
  id: string;
  title: string;
  content: string;
  category: string;
  isPinned: boolean;
  viewCount: number;
  displayDate: string | null;
}

export default function Notices() {
  const [expandedId, setExpandedId] = useState<string | null>(null);

  const { data: notices = [], isLoading } = useQuery<Notice[]>({
    queryKey: ["notices"],
    queryFn: async () => {
      const res = await fetch("/api/notices");
      const data = await res.json();
      return data.success ? data.data : [];
    },
  });

  const sortedNotices = [...notices].sort((a, b) => {
    if (a.isPinned && !b.isPinned) return -1;
    if (!a.isPinned && b.isPinned) return 1;
    const dateA = a.displayDate ? new Date(a.displayDate).getTime() : 0;
    const dateB = b.displayDate ? new Date(b.displayDate).getTime() : 0;
    return dateB - dateA;
  });

  const getCategoryLabel = (category: string) => {
    switch (category) {
      case "important":
        return { label: "중요", className: "bg-red-100 text-red-700" };
      case "event":
        return { label: "이벤트", className: "bg-green-100 text-green-700" };
      case "system":
        return { label: "시스템", className: "bg-blue-100 text-blue-700" };
      default:
        return { label: "일반", className: "bg-gray-100 text-gray-700" };
    }
  };

  const toggleExpand = (id: string) => {
    setExpandedId(expandedId === id ? null : id);
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col">
      <Header />

      <main className="flex-1 container mx-auto px-4 py-8">
        <nav className="flex items-center gap-2 text-sm text-gray-500 mb-6">
          <Link href="/" className="hover:text-black flex items-center gap-1">
            <Home className="w-4 h-4" />
            홈
          </Link>
          <ChevronRight className="w-4 h-4" />
          <span className="text-gray-900">공지사항</span>
        </nav>

        <div className="mb-8">
          <h1 className="text-3xl font-bold text-gray-900 mb-2">공지사항</h1>
          <p className="text-gray-600">라이크잇의 새로운 소식과 공지사항입니다</p>
        </div>

        {isLoading ? (
          <div className="bg-white rounded-xl shadow-sm divide-y">
            {[...Array(5)].map((_, i) => (
              <div key={i} className="p-6 animate-pulse">
                <div className="h-4 bg-gray-200 rounded w-3/4 mb-2" />
                <div className="h-4 bg-gray-200 rounded w-1/4" />
              </div>
            ))}
          </div>
        ) : notices.length === 0 ? (
          <div className="bg-white rounded-xl shadow-sm p-16 text-center">
            <Bell className="w-16 h-16 mx-auto mb-4 text-gray-300" />
            <h3 className="text-xl font-medium text-gray-700 mb-2">등록된 공지사항이 없습니다</h3>
            <p className="text-gray-500">새로운 소식이 곧 올라올 예정입니다</p>
          </div>
        ) : (
          <div className="bg-white rounded-xl shadow-sm overflow-hidden">
            <div className="divide-y divide-gray-100">
              {sortedNotices.map((notice) => {
                const category = getCategoryLabel(notice.category);
                const isExpanded = expandedId === notice.id;

                return (
                  <div
                    key={notice.id}
                    className={`${notice.isPinned ? "bg-yellow-50/50" : ""}`}
                    data-testid={`notice-${notice.id}`}
                  >
                    <button
                      onClick={() => toggleExpand(notice.id)}
                      className="w-full px-6 py-4 flex items-center justify-between hover:bg-gray-50 transition-colors text-left"
                    >
                      <div className="flex items-center gap-3 flex-1 min-w-0">
                        {notice.isPinned && (
                          <Pin className="w-4 h-4 text-red-500 flex-shrink-0" />
                        )}
                        <span
                          className={`text-xs px-2 py-1 rounded flex-shrink-0 ${category.className}`}
                        >
                          {category.label}
                        </span>
                        <span className="font-medium text-gray-900 truncate">
                          {notice.title}
                        </span>
                      </div>
                      <div className="flex items-center gap-4 flex-shrink-0 ml-4">
                        <span className="text-sm text-gray-500 hidden sm:block">
                          {notice.displayDate
                            ? new Date(notice.displayDate).toLocaleDateString("ko-KR")
                            : "-"}
                        </span>
                        <span className="text-sm text-gray-400 hidden sm:block">
                          조회 {notice.viewCount || 0}
                        </span>
                        {isExpanded ? (
                          <ChevronUp className="w-5 h-5 text-gray-400" />
                        ) : (
                          <ChevronDown className="w-5 h-5 text-gray-400" />
                        )}
                      </div>
                    </button>

                    {isExpanded && (
                      <div className="px-6 pb-6 pt-2 bg-gray-50">
                        <div 
                          className="prose prose-sm max-w-none text-gray-700 [&_img]:max-w-full [&_img]:h-auto [&_img]:rounded-lg [&_p]:my-2"
                          dangerouslySetInnerHTML={{ __html: notice.content }}
                        />
                        <div className="mt-4 pt-4 border-t text-sm text-gray-500 sm:hidden">
                          <p>
                            {notice.displayDate
                              ? new Date(notice.displayDate).toLocaleDateString("ko-KR")
                              : "-"}{" "}
                            | 조회 {notice.viewCount || 0}
                          </p>
                        </div>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        )}
      </main>

      <Footer />
    </div>
  );
}

