              <span>&gt;</span>
              <span>고객센터</span>
              <span>&gt;</span>
              <span>FAQ</span>
            </div>
          </div>
        </div>

        <div className="max-w-[1200px] mx-auto px-4 py-8">
          <div className="flex gap-8">
            <aside className="hidden md:block w-48 flex-shrink-0">
              <nav className="border border-gray-200">
                {sideMenuItems.map((item, index) => (
                  <Link
                    key={index}
                    href={item.path}
                    className={`block px-4 py-3 text-sm border-b border-gray-200 last:border-b-0 ${
                      location === item.path 
                        ? 'bg-gray-900 text-white font-medium' 
                        : 'text-gray-700 hover:bg-gray-50'
                    }`}
                  >
                    {item.name}
                  </Link>
                ))}
              </nav>
            </aside>

            <div className="flex-1">
              <div className="mb-6">
                <p className="text-sm text-gray-600">
                  Total : <strong>{faqItems.length}</strong> items
                </p>
              </div>

              <div className="border border-gray-200">
                {faqItems.map((item) => (
                  <div key={item.id} className="border-b border-gray-200 last:border-b-0">
                    <button
                      onClick={() => toggleExpand(item.id)}
                      className="w-full px-4 py-4 flex items-center justify-between hover:bg-gray-50 transition-colors text-left"
                      data-testid={`faq-item-${item.id}`}
                    >
                      <div className="flex items-center gap-3">
                        <span className="text-xs px-2 py-1 bg-gray-100 text-gray-600 rounded">
                          {item.category}
                        </span>
                        <span className="font-medium text-gray-900">{item.question}</span>
                      </div>
                      {expandedId === item.id ? (
                        <ChevronUp className="w-5 h-5 text-gray-400" />
                      ) : (
                        <ChevronDown className="w-5 h-5 text-gray-400" />
                      )}
                    </button>
                    {expandedId === item.id && (
                      <div className="px-4 py-4 bg-gray-50 border-t border-gray-200">
                        <p className="text-sm text-gray-700 leading-relaxed">{item.answer}</p>
                      </div>
                    )}
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      </main>

      <Footer />
    </div>
  );
}

