      );

      const valid = results.filter(r => r !== null);
      const inserted = await saveProducts(valid);
      totalInserted += inserted;

      console.log(`  Chunk ${Math.floor(i/CHUNK_SIZE) + 1}: +${inserted} (Total: ${totalInserted})`);
    }

    console.log(`  [${category.name}] Complete. Running total: ${totalInserted}`);
  }

  console.log(`\n${"=".repeat(60)}`);
  console.log(`COMPLETE! Total products: ${totalInserted}`);
  console.log(`${"=".repeat(60)}`);

  process.exit(0);
